import { getContext, setContext } from 'svelte'
import type { StoreReview, ReviewSummary } from '../review/review-types.js'

// Surface-neutral reviews collection context. Populated by a surface Root
// (Product/Customer/top-level). Carries the product-aggregate concerns
// (`summary`/`productId`) alongside the list, so Summary/Histogram/Form read
// this single context too. No `$effect`.
// Per-item context (`ReviewItemContext`/`setReviewItemContext`/`getReviewItemContextOptional`)
// lives in the dependency-free `review/` atom now — see `review/reviews-item-ctx.svelte.ts`.
export type ReviewsListContext = {
	readonly reviews: StoreReview[]
	readonly count: number
	readonly filteredCount: number
	readonly loading: boolean
	readonly error: unknown
	readonly rating: number | null
	readonly order: string
	readonly page: number
	readonly pageSize: number
	readonly summary: ReviewSummary | null | undefined
	readonly productId: string
	pushReview: (review: StoreReview) => void
	setRating: (n: number | null) => void
	setOrder: (s: string) => void
	setPage: (n: number) => void
}

const REVIEWS = Symbol('reviews')

export function setReviewsContext(ctx: ReviewsListContext) {
	setContext(REVIEWS, ctx)
}
export function getReviewsContext(): ReviewsListContext {
	const ctx = getContext<ReviewsListContext>(REVIEWS)
	if (!ctx) throw new Error('Reviews.* must be used within a <Reviews.Root> / <Customer.Reviews>')
	return ctx
}
export function getReviewsContextOptional(): ReviewsListContext | null {
	return getContext<ReviewsListContext>(REVIEWS) ?? null
}

// Per-bar context for Reviews.Summary.Histogram (set by histogram-level provider).
export type HistogramLevelContext = {
	readonly level: number
	readonly count: number
	readonly fill: number
	readonly active: boolean
	readonly orientation: 'horizontal' | 'vertical'
	select: () => void
}
const LEVEL = Symbol('histogram-level')
export function setHistogramLevelContext(ctx: HistogramLevelContext) {
	setContext(LEVEL, ctx)
}
export function getHistogramLevelContext(): HistogramLevelContext {
	const ctx = getContext<HistogramLevelContext>(LEVEL)
	if (!ctx) throw new Error('Histogram parts must be used within <Reviews.Summary.Histogram>')
	return ctx
}

// Pure collection math for the Reviews components. No Svelte, unit-testable.
// Presentational star/date math (`averageToStarFills`/`ratingToStarFills`/`formatReviewDate`)
// moved to the dependency-free `review/` atom — see `review/review-logic.ts`.

/** Fraction 0–1 of a histogram bar; 0 when there are no reviews. */
export function barFill(count: number, total: number): number {
	return total > 0 ? count / total : 0
}

/** Number of pages for a review count at a given page size. */
export function pageCount(count: number, pageSize: number): number {
	return pageSize > 0 ? Math.ceil((count || 0) / pageSize) : 0
}

import { setReviewFormContext } from './review-form-ctx.svelte.js'
import { resolveReviewMessage, reviewMessages } from './review-form-messages.js'
import type { ReviewForm, ReviewFormResult } from './review-form-ctx.svelte.js'
import type { StoreReview } from '../review/review-types.js'

export interface CreateReviewFormOptions {
	form: ReviewForm
	pushReview: (review: StoreReview) => void
	setOpen: (open: boolean) => void
	messages?: Record<string, string>
	onsuccess?: (review: StoreReview) => void
	onerror?: (result: ReviewFormResult) => void
}

/**
 * Shared code for `Reviews.Form`: provides the review-form context the submit/error
 * parts read, runs the native remote-form submission, maps failure codes to copy, pushes a
 * successful review into the reviews list, and exposes the enhanced `<form>` attributes.
 * Call it once from the form component's top-level script (component-init scope, so the
 * context is set correctly).
 */
export function createReviewForm(options: () => CreateReviewFormOptions) {
	let error = $state('')

	setReviewFormContext({
		get form() {
			return options().form
		},
		get error() {
			return error
		},
		get submitting() {
			return options().form.pending > 0
		},
		get messages() {
			return options().messages ?? reviewMessages
		},
		setOpen: (o) => options().setOpen(o)
	})

	const enhanced = options().form.enhance(async ({ submit }) => {
		error = ''
		const o = options()
		const msgs = o.messages ?? reviewMessages
		try {
			await submit()
		} catch {
			// A thrown submission produced no ReviewFormResult — a transport-level failure
			// (offline, server unreachable, dropped connection). Surface it as in-form copy
			// instead of letting it bubble up unhandled (which renders outside the form).
			const result: ReviewFormResult = { ok: false, code: 'network' }
			error = resolveReviewMessage(msgs, 'network')
			o.onerror?.(result)
			return
		}
		const r = o.form.result
		if (r?.ok) {
			o.pushReview(r.review)
			o.onsuccess?.(r.review)
		} else if (r) {
			error = resolveReviewMessage(msgs, r.code)
			o.onerror?.(r)
		}
	})

	return {
		/** Spread onto the `<form>` element. */
		get enhanced() {
			return enhanced
		},
		/** Clear the form-level error (wire to the form's `oninput`). */
		clearError() {
			error = ''
		}
	}
}

import { getContext, setContext } from 'svelte'
import type { RemoteForm } from '@sveltejs/kit'
import type { StoreReview } from '../review/review-types.js'

// Form-only types: these use `RemoteForm` from `@sveltejs/kit` and so must NOT live in the
// dependency-free `review/` core (see review/review-types.ts for the pure data types).
export type ReviewFormResult = { ok: true; review: StoreReview } | { ok: false; code: string }
export type ReviewForm = RemoteForm<any, ReviewFormResult>
export type ReviewFormContext = {
	readonly form: ReviewForm
	readonly error: string
	readonly submitting: boolean
	readonly messages: Record<string, string>
	setOpen: (open: boolean) => void
}
export type ReviewFormMessages = Record<string, string>

const REVIEW_FORM = Symbol('review-form')

export function setReviewFormContext(ctx: ReviewFormContext) {
	setContext(REVIEW_FORM, ctx)
}
export function getReviewFormContext(): ReviewFormContext {
	const ctx = getContext<ReviewFormContext>(REVIEW_FORM)
	if (!ctx) throw new Error('Reviews.Form.* must be used within <Reviews.Form>')
	return ctx
}

import type { ReviewFormMessages } from './review-form-ctx.svelte.js'

export type { ReviewFormMessages } from './review-form-ctx.svelte.js'

export const reviewMessages: ReviewFormMessages = {
	unauthenticated: 'Please sign in to write a review.',
	error: 'Something went wrong. Please try again.',
	network: 'Could not reach the server. Please check your connection and try again.',
	unknown: 'Something went wrong. Please try again.'
}

export function resolveReviewMessage(messages: ReviewFormMessages, code: string | undefined): string {
	return messages[code ?? 'unknown'] ?? messages.unknown ?? 'Something went wrong. Please try again.'
}

import Root from './reviews-root.svelte'
import List from './reviews-list.svelte'
import SortRoot from './reviews-sort.svelte'

import SummaryRoot from './reviews-summary.svelte'
import SummaryTitle from './reviews-summary-title.svelte'
import SummaryAverage from './reviews-summary-average.svelte'
import SummaryStars from './reviews-summary-stars.svelte'
import SummaryCount from './reviews-summary-count.svelte'
import HistogramRoot from './reviews-histogram.svelte'
import HistogramBar from './reviews-histogram-bar.svelte'
import HistogramLabel from './reviews-histogram-label.svelte'

import PaginationRoot from './reviews-pagination.svelte'
import PaginationPrev from './reviews-pagination-prev.svelte'
import PaginationNext from './reviews-pagination-next.svelte'
import PaginationInfo from './reviews-pagination-info.svelte'

import FormRoot from './reviews-form.svelte'
import FormAuthor from './reviews-form-author.svelte'
import FormRating from './reviews-form-rating.svelte'
import FormTitle from './reviews-form-title.svelte'
import FormBody from './reviews-form-body.svelte'
import FormSubmit from './reviews-form-submit.svelte'
import FormCancel from './reviews-form-cancel.svelte'
import FormError from './reviews-form-error.svelte'

// `reviews/` is the collection namespace: `import * as Reviews from '.../reviews'` gives
// `Reviews.Root`, `Reviews.Summary(.Title/.Average/.Stars/.Count/.Histogram(.Bar/.Label))`,
// `Reviews.Sort`, `Reviews.List`, `Reviews.Pagination(.Prev/.Next/.Info)`,
// `Reviews.Form(.Author/.Rating/.Title/.Body/.Submit/.Cancel/.Error)`, `Reviews.Carousel`.
// Each compound is `Object.assign`-ed onto its own dedicated `*Root` component, and this barrel
// is the SOLE owner/builder of Summary/Histogram/Form — `product/index.ts` no longer rebuilds
// them (it only re-exports `Rating` + `Star`). `Customer.Reviews.Review` still guards against a
// separate cross-family leak by never mutating the shared `Review` compound in place (see
// `customer/index.ts`); that guard is unrelated to Summary/Histogram/Form, which have exactly
// one builder now.
const Histogram = Object.assign(HistogramRoot, { Root: HistogramRoot, Bar: HistogramBar, Label: HistogramLabel })
export const Summary = Object.assign(SummaryRoot, {
	Root: SummaryRoot,
	Title: SummaryTitle,
	Average: SummaryAverage,
	Stars: SummaryStars,
	Count: SummaryCount,
	Histogram
})

export const Sort = SortRoot

export const Pagination = Object.assign(PaginationRoot, {
	Root: PaginationRoot,
	Prev: PaginationPrev,
	Next: PaginationNext,
	Info: PaginationInfo
})

export const Form = Object.assign(FormRoot, {
	Root: FormRoot,
	Author: FormAuthor,
	Rating: FormRating,
	Title: FormTitle,
	Body: FormBody,
	Submit: FormSubmit,
	Cancel: FormCancel,
	Error: FormError
})

export { Root, List }
export { default as Carousel } from './reviews-carousel.svelte'

// Individual exports — `Review` is consumed directly by `customer/index.ts` for its own
// compound-building (`Customer.Reviews.Review`). `product/index.ts` re-exports `Star` from
// `../review/index.js` directly rather than through here (it no longer builds a Reviews compound).
export { default as Review, Star } from '../review/index.js'

export {
	setReviewsContext,
	getReviewsContext,
	getReviewsContextOptional,
	setHistogramLevelContext,
	getHistogramLevelContext
} from './reviews-ctx.svelte.js'
export type { ReviewsListContext, HistogramLevelContext } from './reviews-ctx.svelte.js'

export {
	setReviewItemContext,
	getReviewItemContextOptional
} from '../review/index.js'
export type { ReviewItemContext } from '../review/index.js'

export * as logic from './reviews-logic.js'
// Alias kept for external consumers importing collection logic by this name; `product/index.ts`
// no longer re-exports it (product only re-exports `Rating`/`Star`).
export * as reviewsLogic from './reviews-logic.js'

export type {
	StoreReview,
	ReviewSummary,
	ReviewsListResponse,
	SummaryQuery,
	ReviewsQuery
} from '../review/review-types.js'
